/* 轻量图片灯箱（替代 fancybox）：只实现主题用到的那一个 API —— jQuery(sel).fancybox(opts)
 * 保持原文件路径与调用方式不变，所以 injector 里的初始化脚本无需修改。
 * 无外部请求、无额外依赖；样式由本文件注入。
 */
(function () {
  if (typeof jQuery === 'undefined') return;
  var CSS = ".lb-mask{position:fixed;inset:0;z-index:9999;background:rgba(0,0,0,.88);display:none;align-items:center;justify-content:center}" +
    ".lb-mask.on{display:flex}" +
    ".lb-img{max-width:92vw;max-height:88vh;border-radius:4px;box-shadow:0 10px 40px rgba(0,0,0,.5)}" +
    ".lb-btn{position:absolute;background:rgba(255,255,255,.16);border:0;color:#fff;font-size:24px;line-height:1;cursor:pointer;border-radius:50%;width:42px;height:42px}" +
    ".lb-btn:hover{background:rgba(255,255,255,.3)}" +
    ".lb-close{top:16px;right:16px}.lb-prev{left:16px;top:50%;margin-top:-21px}.lb-next{right:16px;top:50%;margin-top:-21px}" +
    "@media print{.lb-mask{display:none!important}}";
  var mask = null, img = null, group = [], idx = 0;
  function ensure() {
    if (mask) return;
    var st = document.createElement('style'); st.textContent = CSS; document.head.appendChild(st);
    mask = document.createElement('div'); mask.className = 'lb-mask';
    mask.innerHTML = '<img class="lb-img" alt=""><button class="lb-btn lb-close" aria-label="关闭">×</button>' +
      '<button class="lb-btn lb-prev" aria-label="上一张">‹</button><button class="lb-btn lb-next" aria-label="下一张">›</button>';
    document.body.appendChild(mask);
    img = mask.querySelector('.lb-img');
  }
  function show(i) { if (!group.length) return; idx = (i + group.length) % group.length; img.src = group[idx]; mask.classList.add('on'); }
  function close() { if (mask) { mask.classList.remove('on'); img.removeAttribute('src'); } }
  document.addEventListener('click', function (e) {
    if (!mask) return;
    if (e.target === mask) return close();
    if (e.target.classList.contains('lb-close')) return close();
    if (e.target.classList.contains('lb-prev')) return show(idx - 1);
    if (e.target.classList.contains('lb-next')) return show(idx + 1);
  });
  document.addEventListener('keydown', function (e) {
    if (!mask || !mask.classList.contains('on')) return;
    if (e.key === 'Escape') close();
    if (e.key === 'ArrowLeft') show(idx - 1);
    if (e.key === 'ArrowRight') show(idx + 1);
  });
  jQuery.fn.fancybox = function () {
    ensure();
    return this.each(function () {
      if (this.__lbBound) return;
      this.__lbBound = true;
      var self = this;
      self.addEventListener('click', function (ev) {
        ev.preventDefault();
        var sel = self.getAttribute('data-fancybox') || 'gallery';
        group = [].map.call(document.querySelectorAll('[data-fancybox="' + sel + '"]'), function (a) { return a.getAttribute('href'); }).filter(Boolean);
        show(group.indexOf(self.getAttribute('href')));
      });
    });
  };
})();